<?php require_once __DIR__.'/includes/admin_auth_check.php';require_once __DIR__.'/../config/db.php';$revenue=[];$users=[];try{$p=db();$revenue=$p->query("SELECT DATE_FORMAT(created_at,'%Y-%m') month,SUM(amount) total FROM payments WHERE status='success' GROUP BY month ORDER BY month DESC LIMIT 12")->fetchAll();$users=$p->query("SELECT DATE_FORMAT(created_at,'%Y-%m') month,role,COUNT(*) total FROM users GROUP BY month,role ORDER BY month DESC LIMIT 24")->fetchAll();}catch(Throwable $e){}$pageTitle='Reports';require __DIR__.'/../includes/header.php';?><main class="container py-5"><h1 class="h2">Platform reports</h1><div class="profile-section"><canvas id="revenueChart"></canvas></div><table class="table mt-4"><tr><th>Month</th><th>Revenue</th></tr><?php foreach($revenue as $r):?><tr><td><?=e($r['month'])?></td><td>৳<?=number_format((float)$r['total'],2)?></td></tr><?php endforeach;?></table></main><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js"></script><script>new Chart(document.querySelector('#revenueChart'),{type:'bar',data:{labels:<?=json_encode(array_column($revenue,'month'))?>,datasets:[{label:'Revenue',data:<?=json_encode(array_column($revenue,'total'))?>,backgroundColor:'#087f5b'}]}})</script>
